	[1020] = {
		decompose_id = 0,
		name = "三相·梵天",
		compose_id = 0,
		type = 2,
		id = 1020,
		rare = 5,
		desc = "<color=#9A9A9A>修正者介绍</color>\n弥楼衍的创立者，常年以来将帮派事务交予他人，闭门不出研究着「往世书」。\n平日里总是一副很有活力的样子，一有机会就会占人便宜，但遇到正事就会露出自信果断的一面，对决定好的事情向来坚定不移。",
		limit = 0,
		sub_type = 0,
		display_rare = 5,
		icon = "1020",
		use = 0,
		max = 0,
		source = {}
	},
	[1021] = {
		decompose_id = 0,
		name = "曦光·阿尔忒弥斯",
		compose_id = 0,
		type = 2,
		id = 1021,
		rare = 5,
		desc = "<color=#9A9A9A>修正者介绍</color>\n原铃兰骑士团副团长，现任灯塔骑士团团长。是出身于欧莫菲斯名门的贵族大小姐，同时也是星虹议会第五席议员塞勒涅的学生，为人正直、严于律己，也是雅典娜在铃兰骑士团的前辈。",
		limit = 0,
		sub_type = 0,
		display_rare = 5,
		icon = "1021",
		use = 0,
		max = 0,
		source = {}
	},
	[1022] = {
		decompose_id = 0,
