	[1137] = {
		decompose_id = 0,
		name = "谧光之刻·霍德尔",
		compose_id = 0,
		type = 2,
		id = 1137,
		rare = 5,
		desc = "<color=#9A9A9A>修正者介绍</color>\n苏醒于艾因索菲，现为深空之眼第九部门情报科成员。日常处理着深空之眼大量繁杂的情报工作，直接参与作战的时候不多，不过也会作为特工参与一些情报侦查工作。平时为人低调，与人交流时总显得不自信，但工作的专业性在部门内有口皆碑。",
