	[1156] = {
		decompose_id = 0,
		name = "伐灭·伽梨",
		compose_id = 0,
		type = 2,
		id = 1156,
		rare = 5,
		desc = "<color=#9A9A9A>修正者介绍</color>\n弥楼衍里的大姐大，虽然年纪不大，但为人处事显得豪爽成熟，完完全全以姐姐自居。\n照顾着组织中收留的流离失所的孩子，对于造成这些灾难的视骸则非常的厌恶。\n拥有很丰富的生活经验，全部都是在夏什瓦特当地历练出来的技能，比如砍价、烹饪……",
		limit = 0,
