	[1166] = {
		decompose_id = 0,
		name = "星仪·大国主",
		compose_id = 0,
		type = 2,
		id = 1166,
		rare = 5,
		desc = "<color=#9A9A9A>修正者介绍</color>\n一直以来，大国主都是隐科组的重要成员。虽然隐科组的工作大多为研究与开发，但也免不了有需要直面视骸的时候。为此，她特地为自己设计了一套特殊的战斗服——以占星术为基底，并通过神能与科学设备将星象之力具现化。",
