	[1194] = {
		decompose_id = 0,
		name = "悼亡之蝶·海拉",
		compose_id = 0,
		type = 2,
		id = 1194,
		rare = 5,
		desc = "<color=#9A9A9A>修正者介绍</color>\n作为深空之眼中，送葬者小队的成员，从来都是独来独往地执行任务，毫无怨言。\n同时作为冥途旅团的一员，负责处理侵蚀种视骸，能够不被动摇地处理一些拥有人类外表的视骸。",
		limit = 0,
