	},
	[1197] = {
		decompose_id = 0,
		name = "梦影·俄尼里伊",
		compose_id = 0,
		type = 2,
		id = 1197,
		rare = 5,
		desc = "<color=#9A9A9A>修正者介绍</color>\n拥有进入梦境和邀请他人进入梦境能力的修正者。但由于她自己不能很好控制这一能力，现被哈迪斯收养在【缪斯协会】，由哈迪斯的两个人偶女仆照顾。",
		limit = 0,
